"CREATE TABLE support_ui_confirmations(id $id PRIMARY KEY,user_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,action VARCHAR(16) NOT NULL,payload_hmac CHAR(64) NOT NULL,state_hmac CHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,used_at DATETIME(6) NULL,FOREIGN KEY(user_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
