"CREATE TRIGGER support_ui_draft_identity BEFORE UPDATE ON support_ui_drafts FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.user_id<=>NEW.user_id) OR NOT(OLD.session_id<=>NEW.session_id) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.kind<=>NEW.kind) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable draft scope'; END IF; END",
